import React, { PropsWithChildren, ReactNode, useId, useState, useRef, useCallback } from "react";
import { Tooltip as TooltipStyles } from "@airbus/styles";
import { airbus as tokens } from "@airbus/design-tokens";
import clsx from "clsx";
import { createUseStyles } from "../../lib/styling";
import { PopoverPlacement } from "../helperTypes";
import Popper from "../Popper";
import { CommonProps } from "../helperTypes";

export enum TooltipDelay {
  NONE = tokens.time.delay.none,
  MEDIUM = tokens.time.delay.medium,
  LONG = tokens.time.delay.long,
}

type Props = PropsWithChildren<{
  /** Tooltip arrow className */
  arrowClassName?: string;
  /** Tooltip arrow size */
  arrowSize?: number;
  /** Tooltip className */
  className?: string;
  /** disable tooltip */
  disabled?: boolean;
  /**
   * Delay in ms before showing the tooltip
   * @default TooltipDelay.MEDIUM
   */
  enterDelay?: TooltipDelay;
  /**
   * Delay in ms before hiding the tooltip
   * @default TooltipDelay.NONE
   */
  exitDelay?: TooltipDelay;
  /** Tooltip label/content */
  label?: ReactNode;
  /** Large variant */
  large?: boolean;
  /** Callback fired when the tooltip opens */
  onOpen?: (event: Event) => void;
  /** Callback fired when the tooltip closes */
  onClose?: (event: Event) => void;
  /** Tooltip placement */
  placement?: PopoverPlacement;
  /** Target element className */
  targetClassName?: string;
  /** Large tooltip title */
  title?: string;
}>;

export type TooltipProps = Props & CommonProps;

const useStyles = createUseStyles(TooltipStyles, "tooltip");

export const Tooltip = (props: TooltipProps) => {
  const {
    arrowClassName,
    arrowSize = 4,
    children,
    className,
    disabled = false,
    label,
    placement,
    large,
    onClose,
    onOpen,
    targetClassName,
    title,
    enterDelay = TooltipDelay.MEDIUM,
    exitDelay = TooltipDelay.NONE,
    ...rest
  } = props;

  const [rootNode, setRootNode] = useState<HTMLElement | null>(null);
  const [open, setOpen] = useState(false);
  const classes = useStyles();
  const defaultId = `tooltip-${useId()}`;
  const id = props.id || defaultId;
  
  const enterTimer = useRef<ReturnType<typeof setTimeout>>();
  const exitTimer = useRef<ReturnType<typeof setTimeout>>();

  const toggleOpen = useCallback((isOpen: boolean, event: Event) => {
    setOpen(isOpen);

    // Callbacks receive the real browser event (DOM `Event`).
    // Internally we handle React `SyntheticEvent`, but we pass `event.nativeEvent`
    // here so `onOpen`/`onClose` match their public `Event` signature.
    if (isOpen && onOpen) onOpen(event);
    if (!isOpen && onClose) onClose(event);
  }, [onOpen, onClose]);

  // Note: React calls our DOM event props (onMouseOver/onFocus/...) with a `React.SyntheticEvent`.
  // `handleEnter`/`handleLeave` are internal helpers (not exposed as props), so this typing is
  // not a breaking change for consumers adopting the component. Consumers only see the DOM `Event`
  // via the public `onOpen` / `onClose` callbacks.
  const handleEnter = (event: React.SyntheticEvent<HTMLElement>) => {
    // Tooltip trigger events (hover/focus/touch) can bubble up and unintentionally
    // open/close parent tooltips when tooltips are nested.
    // We stop propagation so only the closest Tooltip reacts to the interaction.
    // We intentionally DO NOT call preventDefault(): the browser should still be
    // able to run its native behavior (e.g. focus management, click, text selection).
    event.stopPropagation();

    // Use the element that triggered the interaction as the Popper anchor.
    // Popper positions the tooltip relative to this `referenceNode`.
    setRootNode(event.currentTarget);

    clearTimeout(enterTimer.current);
    clearTimeout(exitTimer.current);
    
    // Multiple events can fire for the same interaction (e.g. hover + focus).
    // If the tooltip is already open, don't schedule another open.
    if (open) return;

    if (enterDelay) {
      enterTimer.current = setTimeout(() => toggleOpen(true, event.nativeEvent), enterDelay);
    } else {
      toggleOpen(true, event.nativeEvent);
    }
  };

  const handleLeave = (event: React.SyntheticEvent<HTMLElement>) => {
    // Stop the event from bubbling up to parent elements
    event.stopPropagation();

    setRootNode(event.currentTarget);

    clearTimeout(enterTimer.current);
    clearTimeout(exitTimer.current);
    if (!open) return;

    if (exitDelay) {
      exitTimer.current = setTimeout(() => toggleOpen(false, event.nativeEvent), exitDelay);
    } else {
      toggleOpen(false, event.nativeEvent);
    }
  };

  // We attach event handlers on a wrapper element instead of cloning children.
  // This avoids passing a `ref` into function components (React warns in React 18)
  // and still works because mouse/focus events bubble from focusable descendants.
  const targetProps = {
    onMouseOver: handleEnter,
    onMouseLeave: handleLeave,
    onTouchStart: handleEnter,
    onTouchEnd: handleLeave,
    onTouchCancel: handleLeave,
    onFocus: handleEnter,
    onBlur: handleLeave,
    className: targetClassName,
  };

  if (!React.isValidElement(children)) {
    return null;
  }

  return (
    <>
      <div
        // Keep a stable reference node for Popper positioning.
        // Note: this is the wrapper element, but `handleEnter/Leave` will
        // update the anchor to the actual interacted element when needed.
        ref={(node) => setRootNode(node)}
        aria-describedby={!disabled && open ? id : undefined}
        {...targetProps}
      >
        {children}
      </div>
      {!disabled && (
        <Popper
          id={id}
          disableRoles
          role="tooltip"
          className={clsx(classes.root, large && classes._large, className)}
          arrowClassName={clsx(classes.arrow, arrowClassName)}
          arrowSize={arrowSize}
          referenceNode={rootNode}
          open={open}
          placement={placement}
          {...rest}
        >
          {title && <div className={classes.title}>{title}</div>}
          {label}
        </Popper>
      )}
    </>
  );
};

export default Tooltip;